class OpenMoveEvalFn:
    def score(self, game, my_player=None):
        """Score the current game state
        Evaluation function that outputs a score equal to how many
        moves are open for AI player on the board minus how many moves
        are open for Opponent's player on the board.

        Note:
            If you think of better evaluation function, do it in CustomEvalFn below.

            Args
                game (Board): The board and game state.
                my_player (Player object): This specifies which player you are.

            Returns:
                float: The current state's score. MyMoves-OppMoves.

            """

        if game.__player_1__ == my_player:
            mmoves= game.get_player_moves(game.__player_1__)
            omoves=game.get_opponent_moves(game.__player_1__)

        if game.__player_2__ == my_player:
            mmoves= game.get_player_moves(game.__player_2__)
            omoves=game.get_opponent_moves(game.__player_2__)

        return (len(mmoves)-len(omoves))


