def alphabeta(player, game, time_left, mords, depth, alpha=float("-inf"), beta=float("inf"), my_turn=True):
    """Implementation of the alphabeta algorithm.

    Args:
        player (CustomPlayer): This is the instantiation of CustomPlayer()
            that represents your agent. It is used to call anything you need
            from the CustomPlayer class (the utility() method, for example,
            or any class variables that belong to CustomPlayer())
        game (Board): A board and game state.
        time_left (function): Used to determine time left before timeout
        depth: Used to track how deep you are in the search tree
        alpha (float): Alpha value for pruning
        beta (float): Beta value for pruning
        my_turn (bool): True if you are computing scores during your turn.

    Returns:
        (tuple, int): best_move, val

    """
    indep=depth
    #print("indep "+str(indep))
    #print(mords)

    def qsearch(gamest,depth,a,b,mvs,ismax):
        scr=player.utility(gamest,ismax)
        if scr >=b:
            return scr
        elif a < scr:
            a=scr
        t=time_left()
        if depth==0 or not mvs or t<=30:
            return scr
        for m in mvs:
            newst, is_over, winner= gamest.forecast_move(m)
            if is_over:
                val=player.utility(newst,not ismax )
            else:
                nmvs=newst.get_active_moves()
                val=qsearch(newst,depth-1,a,b,nmvs,not ismax)
            if ismax:
                if val>=b:
                    return val
                if a < val:
                    a=val
            else:
                if a >=val:
                    return val
                if b > val:
                    b=val
        if ismax:
            return a
        else :
            return b



    def max_val(gamest, depth,a,b):
        val=float('-inf')
        best_move= None
        mvs=gamest.get_active_moves()
        t=time_left()
        if t<=50:
            #val2=player.utility(gamest,True)
            val2=qsearch(gamest,3,a,b,mvs,True)
            #val2=player.utility(gamest,True)
            return None, val2
        if depth == 0 :
            val2=qsearch(gamest,3,a,b,mvs,True)
            #val2=player.utility(gamest,True)
            return None, val2
        ind=indep-depth
        if ind not in mords.keys():
            mords[ind]={}
        omvs = sorted(mvs, key=lambda m: mords[ind].get(m, 0), reverse=True)
        #print(depth)
        #print(ind)
        #print(omvs)
        for m in omvs:
            newst, is_over, winner= gamest.forecast_move(m)
            if is_over:
                newval=player.utility(newst,False)
            else:
                _,newval=min_val(newst, depth-1,a,b)
            if m not in mords[ind].keys():
                mords[ind][m]=newval
            #print(f"{depth} Max eval move {m} utility {newval}")
            if newval > val:
                val=newval
                best_move=m
                #print(f"{depth} Max picked {best_move} val {val}")
            a=max(a,val)
            if val>=b:
                return best_move, val
        return best_move, val


    def min_val(gamest, depth,a,b):


        val=float('inf')
        best_move= None
        mvs=gamest.get_active_moves()
        t=time_left()
        if t<=50:
            #val2=player.utility(gamest,False)
            val2=qsearch(gamest,3,a,b,mvs,False)
            #val2=player.utility(gamest,True)
            return None, val2
        if depth == 0:
            val2=qsearch(gamest,3,a,b,mvs,False)
            #val2=player.utility(gamest,False)
            return None, val2
        ind=indep-depth
        if ind not in mords.keys():
            mords[ind]={}
        omvs = sorted(mvs, key=lambda m: mords[ind].get(m, 0))
        for m in omvs:
            newst, is_over, winner= gamest.forecast_move(m)
            if is_over:
               newval=player.utility(newst,True)
            else :
                _,newval=max_val(newst, depth-1,a,b)
            if m not in mords[ind].keys():
                mords[ind][m]=newval
            #print(f"{depth} Min eval move {m} utility {newval}")
            if newval < val:
                val=newval
                best_move=m
            b=min(b,val)
            if val<=a:
                return best_move, val
                #print(f"{depth} Min picked {best_move} val {val}")


        return best_move, val




    if my_turn:
        best_move, val=max_val(game,depth,alpha,beta)
        return best_move, val,mords
    else:
        best_move, val= min_val(game,depth,alpha,beta)
        return best_move, val ,mords

